import Model from 'flarum/common/Model';
/** `slow-mail-letters`: words only on a single letter (`body`), the journey only for its sender. */
export default class Letter extends Model {
  box = Model.attribute('box');
  body = Model.attribute('body');
  stamp = Model.attribute('stamp');
  replyTo = Model.attribute('replyTo');
  postmark = Model.attribute('postmark');
  origin = Model.attribute('origin');
  words = Model.attribute('words');
  travelHours = Model.attribute('travelHours');
  sentAt = Model.attribute('sentAt');
  deliveredAt = Model.attribute('deliveredAt');
  status = Model.attribute('status');
  arrivesAt = Model.attribute('arrivesAt');
  destination = Model.attribute('destination');
  read = Model.attribute('read');
  sender = Model.hasOne('sender');
  recipient = Model.hasOne('recipient');
}
flarum.reg.add('ernestdefoe-slow-mail', 'forum/models/Letter', Letter);