import Model from 'flarum/common/Model';
/** `slow-mail-reports`: a letter its recipient showed the moderators (moderators read `body`). */
export default class Report extends Model {
  reason = Model.attribute('reason');
  body = Model.attribute('body');
  sentAt = Model.attribute('sentAt');
  reportedAt = Model.attribute('reportedAt');
  resolved = Model.attribute('resolved');
  reporter = Model.hasOne('reporter');
  sender = Model.hasOne('sender');
}
flarum.reg.add('ernestdefoe-slow-mail', 'forum/models/Report', Report);